import{Z as e,e as a,f as o,a0 as n}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"Captcha.Eu","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/captcha-eu.md","filePath":"integrations/captchas/captcha-eu.md","lastUpdated":1781527112000}'),i={name:"integrations/captchas/captcha-eu.md"};function s(r,t,c,h,l,p){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="captcha-eu" tabindex="-1">Captcha.Eu <a class="header-anchor" href="#captcha-eu" aria-label="Permalink to &quot;Captcha.Eu&quot;">​</a></h1><p>Follow the below steps to connect Formie to Captcha.eu.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Captcha.eu</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-captcha-eu-keys" tabindex="-1">Step 2. Get Your Captcha.Eu Keys <a class="header-anchor" href="#step-2-get-your-captcha-eu-keys" aria-label="Permalink to &quot;Step 2. Get Your Captcha.Eu Keys&quot;">​</a></h3><ol><li>Go to <a href="https://www.captcha.eu/" target="_blank" rel="noreferrer">Captcha.eu</a> and create an account, or sign in to an existing one.</li><li>In the dashboard, go to <strong>Domains</strong> and add the domain you want to protect.</li><li>Captcha.eu will generate a <strong>Public Key</strong> and <strong>Rest Key</strong> for that domain.</li><li>Copy both keys.</li></ol><h3 id="step-3-connect-formie-to-captcha-eu" tabindex="-1">Step 3. Connect Formie to Captcha.Eu <a class="header-anchor" href="#step-3-connect-formie-to-captcha-eu" aria-label="Permalink to &quot;Step 3. Connect Formie to Captcha.Eu&quot;">​</a></h3><ol><li>Paste the <strong>Public Key</strong> into the <strong>Public Key</strong> field in Formie.</li><li>Paste the <strong>Rest Key</strong> into the <strong>Rest Key</strong> field in Formie.</li><li>Leave <strong>Endpoint</strong> as <code>https://www.captcha.eu</code> unless Captcha.eu has given you a different endpoint.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Captcha.eu</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the captcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Captcha.eu relies on Formie&#39;s front-end output, so test it on the rendered form after saving your settings.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',14)])])}const g=e(i,[["render",s]]);export{d as __pageData,g as default};
